#!/bin/bash
set -e

# Generate config.php from environment variables injected by Render
cat > /var/www/html/config.php <<EOF
<?php
// Auto-generated by docker-entrypoint.sh — do not edit manually

define('DB_HOST',     getenv('DB_HOST')     ?: '127.0.0.1');
define('DB_PORT',     (int)(getenv('DB_PORT')     ?: 3306));
define('DB_USER',     getenv('DB_USER')     ?: 'root');
define('DB_PASS',     getenv('DB_PASS')     ?: '');
define('DB_NAME',     getenv('DB_NAME')     ?: 'gsb_aircon_system');

define('APP_BASE_URL', getenv('APP_BASE_URL') ?: 'http://localhost');
define('APP_ENV',      getenv('APP_ENV')      ?: 'production');

define('SESSION_LIFETIME', 7200);
define('MAX_LOGIN_ATTEMPTS', 5);
define('LOCKOUT_DURATION',   900);

define('SMTP_HOST', getenv('SMTP_HOST') ?: 'smtp.gmail.com');
define('SMTP_PORT', (int)(getenv('SMTP_PORT') ?: 587));
define('SMTP_USER', getenv('SMTP_USER') ?: '');
define('SMTP_PASS', getenv('SMTP_PASS') ?: '');

if (APP_ENV === 'production') {
    error_reporting(0);
    ini_set('display_errors', '0');
    ini_set('log_errors', '1');
} else {
    error_reporting(E_ALL);
    ini_set('display_errors', '1');
}
EOF

chown www-data:www-data /var/www/html/config.php
chmod 640 /var/www/html/config.php

exec "$@"
